<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Spatie\Permission\Models\Role;use Spatie\Permission\Models\Permission;use Illuminate\Support\Str;
class RoleController extends Controller {public function index(){return view('roles.index',['roles'=>Role::with('permissions')->get(),'permissions'=>Permission::orderBy('name')->get()]);}public function store(Request $r){$d=$r->validate(['name'=>'required|max:100|unique:roles,name','permissions'=>'array','permissions.*'=>'exists:permissions,name']);$role=Role::create(['name'=>$d['name'],'guard_name'=>'web']);$role->syncPermissions($d['permissions']??[]);return back()->with('success','نقش ایجاد شد.');}public function update(Request $r,Role $role){$d=$r->validate(['permissions'=>'array','permissions.*'=>'exists:permissions,name']);$role->syncPermissions($d['permissions']??[]);return back()->with('success','مجوزهای نقش بروزرسانی شد.');}public function destroy(Role $role){abort_if($role->name==='مدیر کل',422,'نقش مدیر کل قابل حذف نیست.');$role->delete();return back()->with('success','نقش حذف شد.');}}
